	public static function supports( string $action ): bool { return in_array( sanitize_key( $action ), self::ACTIONS, true ); }
	public static function action_names(): array { return self::ACTIONS; }
	public static function external_dependency( string $action ): bool { return in_array( sanitize_key( $action ), array( 'accounting_software_sync','ad_campaign_create','ad_budget_pacing_adjust','bid_optimize','creative_ab_test','retargeting_audience_sync','press_release_distribute','marketplace_catalog_sync','data_warehouse_sync' ), true ); }
	private static function v( array $a, string $k, $d = null ) { return array_key_exists( $k, $a ) ? $a[ $k ] : $d; }
	private static function limit( array $a, int $default = 50, int $max = 100 ): int { return max( 1, min( $max, absint( self::v( $a, 'limit', $default ) ) ) ); }
	private static function state(): array { $v = get_option( self::STATE, array() ); return is_array( $v ) ? $v : array(); }
	private static function save_state( array $state ): bool { update_option( self::STATE, $state, false ); return get_option( self::STATE, array() ) === $state; }
	private static function set_state( string $section, string $key, $value ): bool { $s=self::state();$s[$section]=is_array($s[$section]??null)?$s[$section]:array();$s[$section][$key]=$value;return self::save_state($s); }
	private static function get_state( string $section, string $key = '' ) { $s=self::state();$v=$s[$section]??array();return ''===$key?$v:(is_array($v)?($v[$key]??null):null); }
	private static function read_result( array $data, string $evidence ): array { return array_merge( $data, array( 'status'=>'verified','executed'=>true,'mutated'=>false,'verified'=>true,'evidence'=>$evidence ) ); }
	private static function write_result( array $data, bool $verified, string $evidence ): array {
		return array_merge( $data, array( 'status'=>$verified?'completed':'mutated','executed'=>true,'mutated'=>true,'verified'=>$verified,'degraded'=>!$verified,'blocking'=>false,'evidence'=>$evidence ) );
	}
	private static function require_wc() { return function_exists( 'wc_get_product' ) && function_exists( 'wc_get_order' ) ? true : new WP_Error( 'prstudio_wc_required', 'WooCommerce deve essere installato e attivo per questa azione.', array( 'status'=>503,'dependency'=>'woocommerce' ) ); }
	private static function ids( array $payload, string $key='product_ids' ): array { $raw=(array)self::v($payload,$key,self::v($payload,'ids',array()));if(!$raw&&self::v($payload,'id'))$raw=array(self::v($payload,'id'));return array_slice(array_values(array_unique(array_filter(array_map('absint',$raw)))),0,self::MAX_BATCH); }
	private static function uploads_file( string $name ): array { $u=wp_upload_dir();if(!empty($u['error']))return array('error'=>$u['error']);$dir=trailingslashit($u['basedir']).'prstudio';if(!wp_mkdir_p($dir))return array('error'=>'mkdir_failed');$safe=sanitize_file_name($name);return array('path'=>trailingslashit($dir).$safe,'url'=>trailingslashit($u['baseurl']).$safe); }
	private static function redact_sensitive( $value ) {
		if ( ! is_array( $value ) ) { return $value; }
		$out = array();
		foreach ( $value as $key => $item ) {
			$name = strtolower( (string) $key );
			if ( preg_match( '/(?:password|passwd|secret|token|api[_-]?key|authorization|cookie|session|otp|nonce)/i', $name ) ) {
				$out[ $key ] = '[REDACTED]';
				continue;
			}
			$out[ $key ] = is_array( $item ) ? self::redact_sensitive( $item ) : $item;
		}
		return $out;
	}
	private static function external_provider( string $action, array $payload ) {
		$hook='prstudio_enterprise_provider_execute_'.$action;
		if ( ! has_filter( $hook ) ) { return new WP_Error( 'prstudio_external_provider_required', 'L’azione richiede un provider esterno reale. Registrare l’adapter WordPress per il provider già in uso; nessun falso successo viene restituito.', array( 'status'=>503,'action'=>$action,'adapter_hook'=>$hook,'account_or_session_required'=>true ) ); }
		$result=apply_filters($hook,null,$payload,array('action'=>$action,'suite_version'=>'1.0.0'));
		if(is_wp_error($result))return $result;
		if(!is_array($result))return new WP_Error('prstudio_external_provider_invalid','Il provider ha restituito un payload non valido.',array('status'=>502,'action'=>$action));
		$result=self::redact_sensitive($result);
		if(empty($result['executed']))return new WP_Error('prstudio_external_provider_not_executed','Il provider non ha eseguito l’operazione richiesta.',array('status'=>502,'action'=>$action,'result'=>$result));
		if(empty($result['verified'])){$result['status']='degraded';$result['degraded']=true;$result['blocking']=false;$result['verification_warning']='external_provider_effect_unverified';}
		return $result;
	}
	private static function fetch_sources( array $payload ): array {
		$urls=(array)self::v($payload,'source_urls',self::v($payload,'urls',array()));$urls=array_slice(array_values(array_unique(array_filter(array_map('esc_url_raw',$urls)))),0,self::MAX_SOURCES);
		if(!$urls)return array('error'=>new WP_Error('prstudio_sources_required','source_urls/urls obbligatorio per una ricerca esterna senza API.',array('status'=>400)),'items'=>array());
		$items=[];foreach($urls as $url){$r=wp_safe_remote_get($url,array('timeout'=>8,'redirection'=>3,'limit_response_size'=>self::MAX_HTTP_BYTES,'user-agent'=>'PR-STUDIO/1.0.0'));if(is_wp_error($r)){$items[]=array('url'=>$url,'ok'=>false,'error'=>$r->get_error_code());continue;}$code=wp_remote_retrieve_response_code($r);$body=(string)wp_remote_retrieve_body($r);$items[]=array('url'=>$url,'ok'=>$code>=200&&$code<400,'status'=>$code,'body'=>$body,'bytes'=>strlen($body));}return array('items'=>$items);
	}
	private static function text_from_html( string $html, int $max=50000 ): string { $text=html_entity_decode(wp_strip_all_tags($html),ENT_QUOTES|ENT_HTML5,'UTF-8');$text=preg_replace('/\s+/u',' ',trim($text));return mb_substr((string)$text,0,$max); }
	private static function price_from_html( string $html ): ?float {
		if(preg_match('/["\']price["\']\s*:\s*["\']?([0-9]+(?:[\.,][0-9]{1,2})?)/i',$html,$m))return (float)str_replace(',','.',$m[1]);
		if(preg_match('/(?:€|EUR\s*)\s*([0-9]{1,6}(?:[\.,][0-9]{1,2})?)/i',$html,$m))return (float)str_replace(',','.',$m[1]);
		if(preg_match('/([0-9]{1,6}(?:[\.,][0-9]{1,2})?)\s*(?:€|EUR)/i',$html,$m))return (float)str_replace(',','.',$m[1]);
		return null;
	}
	private static function order( array $payload ) { $ok=self::require_wc();if(is_wp_error($ok))return $ok;$id=absint(self::v($payload,'order_id',self::v($payload,'id',0)));$o=$id?wc_get_order($id):false;return $o?:new WP_Error('prstudio_order_required','order_id valido obbligatorio.',array('status'=>400)); }
