	private static function bundle_builder(array $p){$ok=self::require_wc();if(is_wp_error($ok))return $ok;$id=absint(self::v($p,'product_id',self::v($p,'id',0)));$items=self::ids($p,'bundle_product_ids');if(!$id||!wc_get_product($id)||!$items)return new WP_Error('prstudio_bundle_args','product_id e bundle_product_ids validi obbligatori.',array('status'=>400));update_post_meta($id,'_prstudio_bundle_items',$items);update_post_meta($id,'_prstudio_bundle_discount',(float)self::v($p,'discount_percent',0));$after=(array)get_post_meta($id,'_prstudio_bundle_items',true);return self::write_result(array('product_id'=>$id,'bundle_product_ids'=>$after,'discount_percent'=>(float)get_post_meta($id,'_prstudio_bundle_discount',true)),$after===$items,'bundle_meta_readback');}
	private static function marketplace_sync(array $p){
		if ( has_filter( 'prstudio_enterprise_provider_execute_marketplace_catalog_sync' ) ) { return self::external_provider( 'marketplace_catalog_sync', $p ); }
		$mode = sanitize_key( (string) self::v( $p, 'mode', 'sync' ) );
		if ( ! in_array( $mode, array( 'sync', 'export' ), true ) ) { return new WP_Error( 'prstudio_marketplace_mode_invalid', 'mode deve essere sync oppure export.', array( 'status'=>400 ) ); }
		if ( 'sync' === $mode ) { return new WP_Error( 'prstudio_marketplace_provider_required', 'La sincronizzazione verso un marketplace richiede un provider reale già configurato. Usare mode=export solo per produrre un export locale verificato.', array( 'status'=>503, 'action'=>'marketplace_catalog_sync', 'adapter_hook'=>'prstudio_enterprise_provider_execute_marketplace_catalog_sync' ) ); }
		$ok=self::require_wc();if(is_wp_error($ok))return $ok;$ids=self::ids($p);if(!$ids&&function_exists('wc_get_products'))$ids=array_map('absint',wc_get_products(array('limit'=>self::limit($p,100,100),'return'=>'ids','status'=>'publish')));if(!$ids)return new WP_Error('prstudio_marketplace_products_required','Nessun prodotto da esportare.',array('status'=>400));
		$rows=[];foreach($ids as $id){$x=wc_get_product($id);if($x)$rows[]=array('id'=>$id,'sku'=>$x->get_sku(),'name'=>$x->get_name(),'price'=>$x->get_price(),'stock_status'=>$x->get_stock_status(),'permalink'=>get_permalink($id));}
		$f=self::uploads_file('marketplace-catalog-'.gmdate('Ymd-His').'.json');if(isset($f['error']))return new WP_Error('prstudio_marketplace_export_failed',$f['error'],array('status'=>500));$written=file_put_contents($f['path'],wp_json_encode($rows,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES),LOCK_EX);$hash=false!==$written&&is_file($f['path'])?hash_file('sha256',$f['path']):false;
		return self::write_result(array('mode'=>'export','products'=>count($rows),'path'=>$f['path'],'url'=>$f['url'],'sha256'=>$hash?:null,'external_sync'=>false),(bool)$hash,'marketplace_export_hash');
	}

	private static function merchandising(array $p){$ok=self::require_wc();if(is_wp_error($ok))return $ok;$rows=(array)self::v($p,'products',array());if(!$rows){foreach(self::ids($p) as $id)$rows[]=array('id'=>$id,'menu_order'=>self::v($p,'menu_order',0),'featured'=>self::v($p,'featured',null));}if(!$rows)return new WP_Error('prstudio_merch_targets','products/product_ids obbligatori.',array('status'=>400));$out=[];$all=true;foreach(array_slice($rows,0,self::MAX_BATCH) as $r){$id=absint($r['id']??0);$x=wc_get_product($id);if(!$x){$all=false;$out[]=array('id'=>$id,'verified'=>false);continue;}if(array_key_exists('menu_order',$r))$x->set_menu_order((int)$r['menu_order']);if(array_key_exists('featured',$r)&&null!==$r['featured'])$x->set_featured((bool)$r['featured']);$x->save();$y=wc_get_product($id);$v=$y&&(!array_key_exists('menu_order',$r)||$y->get_menu_order()===(int)$r['menu_order'])&&(!array_key_exists('featured',$r)||null===$r['featured']||$y->get_featured()===(bool)$r['featured']);$all=$all&&$v;$out[]=array('id'=>$id,'verified'=>$v,'menu_order'=>$y?$y->get_menu_order():null,'featured'=>$y?$y->get_featured():null);}return self::write_result(array('items'=>$out,'processed'=>count($out)),$all,'woocommerce_product_readback');}
	private static function competitor_prices(array $p,string $action){$f=self::fetch_sources($p);if(isset($f['error']))return $f['error'];$items=[];foreach($f['items'] as $i){$items[]=array('url'=>$i['url'],'ok'=>$i['ok'],'status'=>$i['status']??0,'price'=>!empty($i['body'])?self::price_from_html($i['body']):null,'title'=>!empty($i['body'])&&preg_match('/<title[^>]*>(.*?)<\/title>/is',$i['body'],$m)?self::text_from_html($m[1],240):null);}$prices=array_values(array_filter(array_column($items,'price'),fn($v)=>null!==$v));return self::read_result(array('action'=>$action,'items'=>$items,'prices_found'=>count($prices),'min'=>$prices?min($prices):null,'max'=>$prices?max($prices):null,'average'=>$prices?array_sum($prices)/count($prices):null),'bounded_public_source_fetch');}
	private static function dynamic_pricing(array $p){$ok=self::require_wc();if(is_wp_error($ok))return $ok;$ids=self::ids($p);if(!$ids)return new WP_Error('prstudio_pricing_targets','product_ids obbligatorio.',array('status'=>400));$pct=(float)self::v($p,'percent',self::v($p,'discount_percent',0));$fixed=self::v($p,'sale_price',null);$out=[];$all=true;foreach($ids as $id){$x=wc_get_product($id);if(!$x){$all=false;continue;}$base=(float)$x->get_regular_price();$sale=null!==$fixed?(float)$fixed:max(0,round($base*(1-$pct/100),wc_get_price_decimals()));$x->set_sale_price((string)$sale);$x->save();$y=wc_get_product($id);$v=$y&&(float)$y->get_sale_price()===$sale;$all=$all&&$v;$out[]=array('id'=>$id,'regular_price'=>$base,'sale_price'=>$y?$y->get_sale_price():null,'verified'=>$v);}return self::write_result(array('items'=>$out),$all,'woocommerce_price_readback');}
	private static function schedule_promotion(array $p){$when=(int)self::v($p,'timestamp',0);if(!$when&&!empty($p['start_at']))$when=strtotime((string)$p['start_at']);if(!$when||$when<=time())return new WP_Error('prstudio_promotion_time','timestamp/start_at futuro obbligatorio.',array('status'=>400));$id='promo-'.substr(wp_generate_uuid4(),0,12);$rule=array('id'=>$id,'payload'=>$p,'timestamp'=>$when,'created_at'=>gmdate(DATE_ATOM));if(!self::set_state('promotions',$id,$rule))return new WP_Error('prstudio_promotion_store_failed','Impossibile salvare promozione.',array('status'=>500));$scheduled=wp_schedule_single_event($when,'prstudio_agency_apply_promotion',array($id),true);if(is_wp_error($scheduled))return $scheduled;$next=wp_next_scheduled('prstudio_agency_apply_promotion',array($id));return self::write_result(array('promotion_id'=>$id,'scheduled_at'=>gmdate(DATE_ATOM,$when),'next_run'=>$next),false!==$next,'wp_cron_readback');}
	public static function apply_scheduled_promotion(string $id): void {$rule=self::get_state('promotions',$id);if(!is_array($rule))return;$res=self::dynamic_pricing((array)($rule['payload']??array()));$rule['result']=is_wp_error($res)?array('error'=>$res->get_error_code(),'message'=>$res->get_error_message()):$res;$rule['ran_at']=gmdate(DATE_ATOM);self::set_state('promotions',$id,$rule);}
	private static function currency_prices(array $p){
