	public static function filter_commerce_price( $price, $product ) {
		if ( ! is_object( $product ) || ! method_exists( $product, 'get_id' ) ) { return $price; }
		$numeric = is_numeric( $price ) ? (float) $price : $price;
		$currency = function_exists( 'get_woocommerce_currency' ) ? strtoupper( (string) get_woocommerce_currency() ) : '';
		$map = (array) get_post_meta( (int) $product->get_id(), '_prstudio_currency_prices', true );
		if ( $currency && array_key_exists( $currency, $map ) && is_numeric( $map[ $currency ] ) ) { $numeric = (float) $map[ $currency ]; }
		$wholesale = self::get_state( 'commerce', 'wholesale' );
		if ( is_array( $wholesale ) && ! empty( $wholesale['enabled'] ) && is_user_logged_in() ) {
			$user = wp_get_current_user();
			if ( in_array( 'wholesale_customer', (array) $user->roles, true ) ) { $discount = max( 0.0, min( 100.0, (float) ( $wholesale['discount_percent'] ?? 0 ) ) ); if ( is_numeric( $numeric ) ) { $numeric = round( (float) $numeric * ( 1 - $discount / 100 ), function_exists( 'wc_get_price_decimals' ) ? wc_get_price_decimals() : 2 ); } }
		}
		return $numeric;
	}

	public static function enforce_wholesale_minimum_order(): void {
		$cfg = self::get_state( 'commerce', 'wholesale' ); if ( ! is_array( $cfg ) || empty( $cfg['enabled'] ) || empty( $cfg['minimum_order'] ) || ! is_user_logged_in() || ! function_exists( 'WC' ) || ! WC()->cart ) { return; }
		$user = wp_get_current_user(); if ( ! in_array( 'wholesale_customer', (array) $user->roles, true ) ) { return; }
		$minimum = (float) $cfg['minimum_order']; $subtotal = (float) WC()->cart->get_subtotal(); if ( $subtotal + 0.00001 < $minimum && function_exists( 'wc_add_notice' ) ) { wc_add_notice( sprintf( 'Ordine minimo wholesale: %s', function_exists( 'wc_price' ) ? wp_strip_all_tags( wc_price( $minimum ) ) : (string) $minimum ), 'error' ); }
	}

