	public static function handle_cookie_consent(): void {
		if ( 'POST' !== strtoupper( (string) ( $_SERVER['REQUEST_METHOD'] ?? '' ) ) || empty( $_POST['prstudio_cookie_accept'] ) ) { return; }
		$nonce = sanitize_text_field( wp_unslash( (string) ( $_POST['_prstudio_cookie_nonce'] ?? '' ) ) );
		if ( ! wp_verify_nonce( $nonce, 'prstudio_cookie_accept' ) ) { return; }
		setcookie( 'prstudio_cookie_consent', '1', array( 'expires' => time() + YEAR_IN_SECONDS, 'path' => COOKIEPATH ?: '/', 'domain' => COOKIE_DOMAIN ?: '', 'secure' => is_ssl(), 'httponly' => true, 'samesite' => 'Lax' ) );
		$_COOKIE['prstudio_cookie_consent'] = '1';
		$target = wp_get_referer();
		wp_safe_redirect( $target ? $target : home_url( '/' ) );
		exit;
	}
	public static function render_cookie_consent(): void {
		$c = self::get_state( 'legal', 'cookie_consent' );
		if ( ! is_array( $c ) || empty( $c['enabled'] ) || ! empty( $_COOKIE['prstudio_cookie_consent'] ) ) { return; }
		echo '<div id="prstudio-cookie-consent" role="region" aria-label="Cookie" style="position:fixed;z-index:2147483000;left:1rem;right:1rem;bottom:1rem;padding:1rem;background:#111;color:#fff">' . esc_html( (string) $c['message'] ) . ' ';
		if ( ! empty( $c['policy_url'] ) ) { echo '<a style="color:#fff;text-decoration:underline" href="' . esc_url( $c['policy_url'] ) . '">Privacy</a> '; }
		echo '<form method="post" style="display:inline"><input type="hidden" name="prstudio_cookie_accept" value="1"><input type="hidden" name="_prstudio_cookie_nonce" value="' . esc_attr( wp_create_nonce( 'prstudio_cookie_accept' ) ) . '"><button type="submit">OK</button></form></div>';
	}
