	private static function state_record( string $section, array $p, string $idkey ) {
		$operation = sanitize_key( (string) self::v( $p, 'operation', 'upsert' ) );
		$records = self::get_state( $section ); $records = is_array( $records ) ? $records : array();
		$id = sanitize_key( (string) self::v( $p, $idkey, self::v( $p, 'id', '' ) ) );
		if ( 'list' === $operation ) { return self::read_result( array( 'items' => array_values( $records ), 'count' => count( $records ), 'section' => $section ), 'state_collection_readback' ); }
		if ( 'get' === $operation ) { if ( ! $id || ! isset( $records[ $id ] ) ) { return new WP_Error( 'prstudio_state_record_missing', 'Record non trovato.', array( 'status' => 404, 'section' => $section, $idkey => $id ) ); } return self::read_result( array( $idkey => $id, 'record' => $records[ $id ] ), 'state_record_readback' ); }
		if ( 'delete' === $operation ) {
			if ( ! $id || ! isset( $records[ $id ] ) ) { return new WP_Error( 'prstudio_state_record_missing', 'Record non trovato.', array( 'status' => 404, 'section' => $section, $idkey => $id ) ); }
			$state = self::state(); unset( $state[ $section ][ $id ] ); if ( empty( $state[ $section ] ) ) { $state[ $section ] = array(); } $ok = self::save_state( $state ); $after = self::get_state( $section, $id );
			return self::write_result( array( $idkey => $id, 'deleted' => true, 'section' => $section ), $ok && null === $after, 'state_delete_readback' );
		}
		if ( 'transition' === $operation ) {
			if ( ! $id || ! isset( $records[ $id ] ) ) { return new WP_Error( 'prstudio_state_record_missing', 'Record non trovato per la transizione.', array( 'status' => 404, 'section' => $section, $idkey => $id ) ); }
			$status = sanitize_key( (string) self::v( $p, 'status', '' ) ); if ( ! $status ) { return new WP_Error( 'prstudio_state_status_required', 'status è obbligatorio per transition.', array( 'status' => 400 ) ); }
			$record = $records[ $id ]; $record['status'] = $status; $record['updated_at'] = gmdate( DATE_ATOM ); $record['history'] = is_array( $record['history'] ?? null ) ? $record['history'] : array(); $record['history'][] = array( 'status' => $status, 'at' => $record['updated_at'], 'note' => sanitize_text_field( (string) self::v( $p, 'note', '' ) ) );
			$ok = self::set_state( $section, $id, $record ); return self::write_result( array( $idkey => $id, 'record' => $record ), $ok && self::get_state( $section, $id ) === $record, 'state_transition_readback' );
		}
		if ( ! in_array( $operation, array( 'upsert','set' ), true ) ) { return new WP_Error( 'prstudio_state_operation_invalid', 'Operazione lifecycle non valida.', array( 'status' => 400, 'operation' => $operation, 'section' => $section ) ); }
		if ( ! $id ) { $id = sanitize_key( $section . '-' . substr( wp_generate_uuid4(), 0, 12 ) ); }
		$current = is_array( $records[ $id ] ?? null ) ? $records[ $id ] : array(); $data = self::redact_sensitive( $p ); unset( $data['operation'], $data[ $idkey ], $data['id'] );
		$record = array_replace( $current, array( 'id' => $id, 'data' => array_replace( is_array( $current['data'] ?? null ) ? $current['data'] : array(), $data ), 'status' => sanitize_key( (string) self::v( $p, 'status', $current['status'] ?? 'active' ) ), 'created_at' => $current['created_at'] ?? gmdate( DATE_ATOM ), 'updated_at' => gmdate( DATE_ATOM ) ) );
		$ok = self::set_state( $section, $id, $record ); return self::write_result( array( $idkey => $id, 'record' => $record, 'lifecycle_operations' => array( 'list','get','upsert','transition','delete' ) ), $ok && self::get_state( $section, $id ) === $record, 'state_lifecycle_readback' );
	}
