	private static function ab_create(array $p){
		$id=sanitize_key((string)self::v($p,'experiment_id',''));if(!$id)$id='ab-'.substr(wp_generate_uuid4(),0,12);
		$raw=(array)self::v($p,'variants',array());if(count($raw)<2)return new WP_Error('prstudio_ab_variants','Sono richieste almeno due variants.',array('status'=>400));
		$host=(string)wp_parse_url(home_url('/'),PHP_URL_HOST);$variants=[];$seen=[];$i=0;
