		if(count($variants)<2)return new WP_Error('prstudio_ab_variants_invalid','Sono richieste almeno due variants same-origin valide e univoche.',array('status'=>400));
		$status=sanitize_key((string)self::v($p,'status','draft'));if(!in_array($status,array('draft','active','paused','completed'),true))return new WP_Error('prstudio_ab_status_invalid','status deve essere draft, active, paused o completed.',array('status'=>400));
		$target=(string)self::v($p,'target_path','');if($target){$target=(string)wp_parse_url(home_url('/'.ltrim($target,'/')),PHP_URL_PATH);}if('active'===$status&&!$target)return new WP_Error('prstudio_ab_target_required','target_path è obbligatorio per un esperimento active.',array('status'=>400));foreach($variants as $v)if($target&&$v['path']===$target)return new WP_Error('prstudio_ab_redirect_loop','Una variant non può coincidere con target_path: produrrebbe un redirect loop.',array('status'=>400,'variant'=>$v['key']));
		$previous=self::get_state('ab_tests',$id);$stats=is_array($previous)&&is_array($previous['stats']??null)?$previous['stats']:array('exposures'=>array(),'conversions'=>array());foreach($variants as $v){$stats['exposures'][$v['key']]=(int)($stats['exposures'][$v['key']]??0);$stats['conversions'][$v['key']]=(int)($stats['conversions'][$v['key']]??0);}
