	private static function ab_status(array $p){$id=sanitize_key((string)self::v($p,'experiment_id',self::v($p,'id','')));$r=$id?self::get_state('ab_tests',$id):null;if(!$r)return new WP_Error('prstudio_ab_not_found','experiment_id non trovato.',array('status'=>404));$stats=(array)($r['stats']??array());$rates=[];foreach((array)($r['variants']??array()) as $v){$key=(string)($v['key']??'');$e=(int)($stats['exposures'][$key]??0);$c=(int)($stats['conversions'][$key]??0);$rates[$key]=array('exposures'=>$e,'conversions'=>$c,'conversion_rate'=>$e>0?$c/$e:0.0);}return self::read_result(array('experiment'=>$r,'variant_metrics'=>$rates),'ab_runtime_state');}
	public static function apply_ab_tests(): void {
		if(is_admin()||defined('REST_REQUEST')&&REST_REQUEST||!in_array(strtoupper((string)($_SERVER['REQUEST_METHOD']??'GET')),array('GET','HEAD'),true))return;$tests=(array)self::get_state('ab_tests');if(!$tests)return;$request_path=(string)wp_parse_url((string)($_SERVER['REQUEST_URI']??'/'),PHP_URL_PATH);$host=(string)wp_parse_url(home_url('/'),PHP_URL_HOST);
		foreach($tests as $id=>$test){if(!is_array($test)||'active'!==($test['status']??''))continue;$variants=(array)($test['variants']??array());if(count($variants)<2)continue;$cookie='prstudio_ab_'.substr(hash('sha256',(string)$id),0,16);$assigned=sanitize_key((string)($_COOKIE[$cookie]??''));$variant=null;foreach($variants as $v)if(($v['key']??'')===$assigned){$variant=$v;break;}
			$conv_param=sanitize_key((string)($test['conversion_query_param']??'prstudio_ab_conversion'));if($assigned&&isset($_GET[$conv_param])&&sanitize_key((string)wp_unslash($_GET[$conv_param]))===sanitize_key((string)$id)){$conv_cookie=$cookie.'_conv';if(empty($_COOKIE[$conv_cookie])){$test['stats']['conversions'][$assigned]=(int)($test['stats']['conversions'][$assigned]??0)+1;self::set_state('ab_tests',(string)$id,$test);setcookie($conv_cookie,'1',array('expires'=>time()+30*DAY_IN_SECONDS,'path'=>'/','secure'=>is_ssl(),'httponly'=>true,'samesite'=>'Lax'));}}
			if(!$test['target_path']||$request_path!==$test['target_path'])continue;if(!$variant){$total=0;foreach($variants as $v)$total+=max(1,(int)($v['weight']??1));$pick=wp_rand(1,max(1,$total));$cursor=0;foreach($variants as $v){$cursor+=max(1,(int)($v['weight']??1));if($pick<=$cursor){$variant=$v;break;}}if(!$variant)$variant=$variants[0];$assigned=(string)$variant['key'];setcookie($cookie,$assigned,array('expires'=>time()+30*DAY_IN_SECONDS,'path'=>'/','secure'=>is_ssl(),'httponly'=>true,'samesite'=>'Lax'));$test['stats']['exposures'][$assigned]=(int)($test['stats']['exposures'][$assigned]??0)+1;self::set_state('ab_tests',(string)$id,$test);}
			$url=esc_url_raw((string)($variant['url']??''));if(!$url||strcasecmp((string)wp_parse_url($url,PHP_URL_HOST),$host)!==0)continue;$dest_path=(string)wp_parse_url($url,PHP_URL_PATH);if($dest_path===$request_path)continue;if(function_exists('add_query_arg'))$url=add_query_arg('prstudio_ab_variant',$assigned,$url);wp_safe_redirect($url,302,'PR STUDIO AB Test');exit;
		}
	}

