	private static function review_monitor(array $p){$f=self::fetch_sources($p);if(isset($f['error']))return $f['error'];$items=[];$ratings=[];foreach($f['items'] as $i){$text=self::text_from_html((string)($i['body']??''),10000);$rating=null;if(preg_match('/(?:rating|valutazione)[^0-9]{0,20}([0-5](?:[\.,][0-9])?)/i',$text,$m))$rating=(float)str_replace(',','.',$m[1]);if(null!==$rating)$ratings[]=$rating;$items[]=array('url'=>$i['url'],'status'=>$i['status']??0,'rating'=>$rating,'snippet'=>mb_substr($text,0,500));}return self::read_result(array('items'=>$items,'ratings_found'=>count($ratings),'average'=>$ratings?array_sum($ratings)/count($ratings):null),'bounded_review_source_scan');}
	private static function crisis(array $p){$text=mb_strtolower(sanitize_textarea_field((string)self::v($p,'text','')));$keywords=(array)self::v($p,'keywords',array('truffa','frode','richiamo','pericolo','intossicazione','data breach','violazione dati','scam','fraud'));$source_hits=[];if(!empty($p['source_urls'])){$f=self::fetch_sources($p);if(isset($f['error']))return $f['error'];foreach($f['items'] as $i)$text.=' '.mb_strtolower(self::text_from_html((string)($i['body']??''),20000));}$hits=[];foreach($keywords as $k){$k=mb_strtolower(sanitize_text_field((string)$k));if($k&&str_contains($text,$k))$hits[]=$k;}$score=min(100,count($hits)*20);return self::read_result(array('hits'=>$hits,'score'=>$score,'severity'=>$score>=60?'high':($score>=20?'medium':'low'),'automated_heuristic'=>true),'keyword_risk_scan');}
